import{_ as a,o as t,c as s,a2 as n}from"./chunks/framework.doxMM-x8.js";const u=JSON.parse('{"title":"Shared Interface Components","description":"","frontmatter":{"docLocale":"en","counterpart":"/tutorials/design-system","contentType":"guide","prev":false,"next":false},"headers":[],"relativePath":"en/tutorials/design-system.md","filePath":"en/tutorials/design-system.md"}'),o={name:"en/tutorials/design-system.md"};function r(i,e,c,d,l,p){return t(),s("div",null,[...e[0]||(e[0]=[n(`<h1 id="shared-interface-components" tabindex="-1">Shared Interface Components <a class="header-anchor" href="#shared-interface-components" aria-label="Permalink to &quot;Shared Interface Components&quot;">​</a></h1><p>Goal: reuse Lab Word components and tokens and inspect their states in the showroom. Start and sign in using <a href="./../getting-started/quickstart">quick start</a>.</p><h2 id="inspect-a-real-component" tabindex="-1">Inspect A Real Component <a class="header-anchor" href="#inspect-a-real-component" aria-label="Permalink to &quot;Inspect A Real Component&quot;">​</a></h2><p>Open settings from the account entry at the lower left, then open the design system. Inspect a button, input or another existing scene in light/dark, disabled and error states. Showroom data is simulated and does not change equipment or knowledge resources.</p><p>The <a href="https://github.com/CaiZongyuan/labworld/blob/5fe346857c30fec312a9aab1fa984f5d298dcd3b/packages/views/src/design-system/design-system-view.tsx" target="_blank" rel="noreferrer">design-system View</a>composes scenes. Shared implementations include <a href="https://github.com/CaiZongyuan/labworld/blob/5fe346857c30fec312a9aab1fa984f5d298dcd3b/packages/ui/src/components/button.tsx" target="_blank" rel="noreferrer">Button</a>and <a href="https://github.com/CaiZongyuan/labworld/blob/5fe346857c30fec312a9aab1fa984f5d298dcd3b/packages/ui/src/components/input.tsx" target="_blank" rel="noreferrer">Input</a>under <code>packages/ui/src/components/</code>. <a href="https://github.com/CaiZongyuan/labworld/blob/5fe346857c30fec312a9aab1fa984f5d298dcd3b/packages/ui/src/styles.css" target="_blank" rel="noreferrer">styles.css</a>owns color and sizing tokens.</p><h2 id="use-them-in-lab" tabindex="-1">Use Them In Lab <a class="header-anchor" href="#use-them-in-lab" aria-label="Permalink to &quot;Use Them In Lab&quot;">​</a></h2><p>Import existing components from <code>@labos-threejs/ui/components/...</code>. Equipment selection, GLB import and asset information belong to Lab views; shared UI does not import equipment rules. Before adding a component, confirm existing controls cannot express the required state. Pass business state through explicit parameters.</p><p>Denied business access must produce a clear result; disabled buttons do not replace server authorization. Loading and error states retain stable control sizes and keyboard focus. Check narrow screens and both languages for overlapping text.</p><h2 id="validate" tabindex="-1">Validate <a class="header-anchor" href="#validate" aria-label="Permalink to &quot;Validate&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vitest</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apps/web/src/design-system.test.tsx</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> typecheck</span></span></code></pre></div><p>Run from the repository root. View checks observe showroom interactions; type checking validates component contracts. Inspect actual layout, theme and focus in the browser. See <a href="./../guides/lab-viewer">Viewer validation boundaries</a>for real 3D rendering.</p><hr><p>Source version：<code>5fe346857c30</code> · <a href="https://github.com/CaiZongyuan/labworld/blob/5fe346857c30fec312a9aab1fa984f5d298dcd3b/docs/guides/design-system.en.md" target="_blank" rel="noreferrer">Page Markdown</a></p>`,13)])])}const m=a(o,[["render",r]]);export{u as __pageData,m as default};
